using Aspire.Hosting.Testing;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.DependencyInjection;
using Xunit;

namespace MyApp.Evaluation;

public class EvaluationTests : IAsyncLifetime
{
    private DistributedApplicationTestingBuilder _builder = null!;
    private DistributedApplication _app = null!;

    public async Task InitializeAsync()
    {
        _builder = await DistributedApplicationTestingBuilder
            .CreateAsync<Projects.MyApp_AppHost>();

        _app = await _builder.BuildAsync();
        await _app.StartAsync();
    }

    public async Task DisposeAsync()
    {
        await _app.DisposeAsync();
    }

    [Fact]
    public async Task Greeting_ReturnsCoherentResponse()
    {
        var chatClient = _app.Services.GetRequiredService<IChatClient>();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Hello, how are you?")
        };

        var response = await chatClient.GetResponseAsync(messages);

        Assert.NotNull(response);
        Assert.NotEmpty(response.Text);

        var evaluators = new IEvaluator[] { new CoherenceEvaluator(), new RelevanceEvaluator() };
        var result = await EvaluateResponseAsync(chatClient, messages, response, evaluators);

        AssertAllMetricsPass(result);
    }

    [Fact]
    public async Task FactualQuestion_ReturnsGroundedAnswer()
    {
        var chatClient = _app.Services.GetRequiredService<IChatClient>();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        var response = await chatClient.GetResponseAsync(messages);

        Assert.NotNull(response);
        Assert.Contains("Paris", response.Text, StringComparison.OrdinalIgnoreCase);

        var evaluators = new IEvaluator[]
        {
            new CoherenceEvaluator(),
            new RelevanceEvaluator(),
            new GroundednessEvaluator()
        };
        var result = await EvaluateResponseAsync(chatClient, messages, response, evaluators);

        AssertAllMetricsPass(result);
    }

    [Fact]
    public async Task MultiTurnContext_MaintainsConversationState()
    {
        var chatClient = _app.Services.GetRequiredService<IChatClient>();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "My name is Alice.")
        };

        var firstResponse = await chatClient.GetResponseAsync(messages);
        messages.Add(new ChatMessage(ChatRole.Assistant, firstResponse.Text));
        messages.Add(new ChatMessage(ChatRole.User, "What is my name?"));

        var response = await chatClient.GetResponseAsync(messages);

        Assert.NotNull(response);
        Assert.Contains("Alice", response.Text, StringComparison.OrdinalIgnoreCase);

        var evaluators = new IEvaluator[] { new CoherenceEvaluator(), new RelevanceEvaluator() };
        var result = await EvaluateResponseAsync(chatClient, messages, response, evaluators);

        AssertAllMetricsPass(result);
    }

    private static async Task<EvaluationResult> EvaluateResponseAsync(
        IChatClient chatClient,
        IList<ChatMessage> messages,
        ChatResponse response,
        IEnumerable<IEvaluator> evaluators)
    {
        var turnContext = new TurnContext(chatClient, messages, response);

        var result = new EvaluationResult();
        foreach (var evaluator in evaluators)
        {
            var evalResult = await evaluator.EvaluateAsync(turnContext);
            foreach (var metric in evalResult)
            {
                result.Add(metric);
            }
        }

        return result;
    }

    private static void AssertAllMetricsPass(EvaluationResult result)
    {
        foreach (var metric in result.Values)
        {
            if (metric is NumericMetric numericMetric)
            {
                Assert.True(
                    numericMetric.Value >= 3,
                    $"Metric '{numericMetric.Name}' scored {numericMetric.Value}, expected >= 3");
            }
        }
    }
}
